   1 import HuggingFaceAuth
   2 import ReachyDesign
   3 import ReachyKit
   4 import SwiftUI
   5 
   6 /// The Hugging Face account this app holds, and whether this robot shares it.
   7 ///
   8 /// Two custody points, and the card keeps them visibly apart: signing in here
   9 /// gets the private half of the app store and the robot list; *linking* hands the
  10 /// robot its own copy of the token, which is what puts it on the relay. Signing
  11 /// out does not unlink — a robot left reachable with a token the user believes
  12 /// they revoked is the one outcome worth going out of the way to prevent.
  13 struct HFAccountSection: View {
  14     let session: RobotSession
  15 
  16     @State private var model: HFSignInModel
  17     @State private var robotAccount: HFAuthStatus?
  18     @State private var relay: RelayStatus?
  19     @State private var linkError: String?
  20     @State private var isLinking = false
  21     @State private var showsTokenField = false
  22     @State private var confirmingUnlink = false
  23     @Environment(\.reachyPreviewMode) private var previewMode
  24 
  25     init(
  26         session: RobotSession,
  27         model: HFSignInModel,
  28         robotAccount: HFAuthStatus? = nil,
  29         relay: RelayStatus? = nil,
  30         linkError: String? = nil
  31     ) {
  32         self.session = session
  33         _model = State(initialValue: model)
  34         _robotAccount = State(initialValue: robotAccount)
  35         _relay = State(initialValue: relay)
  36         _linkError = State(initialValue: linkError)
  37     }
  38 
  39     var body: some View {
  40         Section {
  41             accountRow
  42             if model.isBusy {
  43                 ProgressView()
  44             }
  45             if let errorText = model.errorText {
  46                 Text(errorText)
  47                     .font(Typography.status)
  48                     .foregroundStyle(Tone.danger.style)
  49             }
  50             signInControls
  51         } header: {
  52             Text(.reachy("Hugging Face"))
  53         } footer: {
  54             Text(footerText)
  55         }
  56 
  57         if session.canLinkHuggingFace {
  58             robotSection
  59         } else if session.canUnlinkRobot {
  60             relayRobotSection
  61         }
  62     }
  63 
  64     // MARK: This robot, over the relay
  65 
  66     /// What a relayed session can honestly say about the robot's account: it holds
  67     /// a token, and that token can be taken away.
  68     ///
  69     /// "Linked" is an inference rather than a reading, and a sound one — this
  70     /// session arrived through central, which lists a robot only while it holds a
  71     /// token. Everything else on the full card needs routes the data channel does
  72     /// not carry, so none of it is shown rather than shown broken.
  73     ///
  74     /// Confirmed, unlike the same button on the local card. There the robot is on
  75     /// the network in front of you and linking it again is the row above; here the
  76     /// robot leaves the relay and only somebody standing next to it can undo that.
  77     private var relayRobotSection: some View {
  78         Section {
  79             LabeledContent(.reachy("This robot"), value: String(localized: .reachy("Linked")))
  80             if let linkError {
  81                 Text(linkError)
  82                     .font(Typography.status)
  83                     .foregroundStyle(Tone.danger.style)
  84             }
  85             Button(.reachy("Unlink this robot"), role: .destructive) {
  86                 confirmingUnlink = true
  87             }
  88             .disabled(isLinking)
  89         } header: {
  90             Text(.reachy("Robot account"))
  91         } footer: {
  92             Text(
  93                 .reachy(
  94                     // swiftlint:disable:next line_length
  95                     "Unlinking takes the robot off the relay: it goes offline and comes back only once somebody sets it up again in person."
  96                 )
  97             )
  98         }
  99         .confirmationDialog(
 100             .reachy("Take the robot off the relay?"),
 101             isPresented: $confirmingUnlink,
 102             titleVisibility: .visible
 103         ) {
 104             Button(.reachy("Unlink this robot"), role: .destructive) {
 105                 Task { await unlink() }
 106             }
 107         } message: {
 108             Text(
 109                 .reachy(
 110                     // swiftlint:disable:next line_length
 111                     "The robot drops its token and leaves the relay. Nothing here can reach it again until it is set up in person."
 112                 )
 113             )
 114         }
 115     }
 116 
 117     // MARK: This app's account
 118 
 119     @ViewBuilder
 120     private var accountRow: some View {
 121         switch model.account.state {
 122         case .signedOut, .signingIn:
 123             Label(.reachy("Not signed in"), systemImage: "person.crop.circle")
 124         case let .signedIn(username):
 125             LabeledContent {
 126                 Button(.reachy("Sign out"), role: .destructive) { model.signOut() }
 127                     .buttonStyle(.borderless)
 128             } label: {
 129                 accountLabel(username: username, caption: String(localized: .reachy("Signed in")))
 130             }
 131         case let .needsReauth(username):
 132             accountLabel(
 133                 username: username ?? String(localized: .reachy("Your account")),
 134                 caption: String(localized: .reachy("Session expired"))
 135             )
 136         case let .failed(reason):
 137             Label(reason, systemImage: "exclamationmark.triangle")
 138                 .foregroundStyle(Tone.warning.style)
 139         }
 140     }
 141 
 142     private func accountLabel(username: String, caption: String) -> some View {
 143         HStack(spacing: 10) {
 144             HFAvatar(username: username)
 145             VStack(alignment: .leading, spacing: 1) {
 146                 Text(username)
 147                 Text(caption)
 148                     .font(Typography.status)
 149                     .foregroundStyle(.secondary)
 150             }
 151         }
 152     }
 153 
 154     @ViewBuilder
 155     private var signInControls: some View {
 156         switch model.account.state {
 157         case .signedIn:
 158             EmptyView()
 159         default:
 160             if model.offersBrowserSignIn {
 161                 Button {
 162                     Task { await model.signInWithBrowser() }
 163                 } label: {
 164                     Label(.reachy("Sign in with Hugging Face"), systemImage: "person.badge.key")
 165                 }
 166                 .disabled(model.isBusy)
 167             }
 168 
 169             DisclosureGroup(String(localized: .reachy("Use an access token")), isExpanded: $showsTokenField) {
 170                 SecureField(.reachy("hf_xxx…"), text: $model.pastedToken)
 171                     .textContentType(.password)
 172                     .autocorrectionDisabled()
 173                 #if os(iOS)
 174                     .textInputAutocapitalization(.never)
 175                 #endif
 176                 Button(.reachy("Sign in with this token")) {
 177                     Task { await model.signInWithPastedToken() }
 178                 }
 179                 .disabled(model.pastedToken.trimmingCharacters(in: .whitespaces).isEmpty || model.isBusy)
 180             }
 181         }
 182     }
 183 
 184     private var footerText: String {
 185         if model.offersBrowserSignIn {
 186             String(
 187                 localized: .reachy(
 188                     "Signing in shows your private Spaces in the app store and lists your robots for remote access."
 189                 )
 190             )
 191         } else {
 192             // Honest about the state of the build rather than showing a button
 193             // that would open an error page on the Hub.
 194             String(
 195                 localized: .reachy(
 196                     // swiftlint:disable:next line_length
 197                     "One-tap sign-in is not available in this build. Create an access token at huggingface.co/settings/tokens and paste it here."
 198                 )
 199             )
 200         }
 201     }
 202 
 203     // MARK: This robot
 204 
 205     private var robotSection: some View {
 206         Section {
 207             LabeledContent(.reachy("This robot"), value: robotAccountText)
 208             if let relay {
 209                 LabeledContent(.reachy("Remote access"), value: relayText(relay))
 210             }
 211             if let linkError {
 212                 Text(linkError)
 213                     .font(Typography.status)
 214                     .foregroundStyle(Tone.danger.style)
 215             }
 216             if robotAccount?.isLoggedIn == true {
 217                 Button(.reachy("Unlink this robot"), role: .destructive) {
 218                     Task { await unlink() }
 219                 }
 220                 .disabled(isLinking)
 221             } else if case .signedIn = model.account.state {
 222                 Button {
 223                     Task { await link() }
 224                 } label: {
 225                     if isLinking {
 226                         ProgressView()
 227                     } else {
 228                         Label(.reachy("Link this robot"), systemImage: "link")
 229                     }
 230                 }
 231                 .disabled(isLinking)
 232             }
 233         } header: {
 234             Text(.reachy("Robot account"))
 235         } footer: {
 236             // The LAN hop is plain HTTP and unauthenticated (ADR 0001). Saying so
 237             // is the honest alternative to implying a security this transport does
 238             // not have.
 239             Text(
 240                 .reachy(
 241                     // swiftlint:disable:next line_length
 242                     "Linking copies your token to the robot over the local network, which is not encrypted. Do it on a network you trust."
 243                 )
 244             )
 245         }
 246         .task {
 247             guard !previewMode else { return }
 248             await loadRobotState()
 249         }
 250     }
 251 
